'use client'

import { useState } from 'react'
import type { HbIcons } from './types'
import { In } from './In'
import { useReducedMotion } from './motion'
import styles from './handbook.module.css'

export function Chain({ title, steps, icons, compact }: { title?: string; steps: { text: string; note?: string; ink?: string }[]; icons: HbIcons; compact?: boolean }) {
  const reduce = useReducedMotion()
  const [k, setK] = useState(0)
  const shown = reduce || compact ? steps.length - 1 : k
  return (
    <div>
      {title && <In as="b" className={styles.ttl} text={title} icons={icons} />}
      <ol className={styles.chain}>
        {steps.map((s, i) => (
          <li key={i} data-step data-on={i <= shown || undefined} className={s.ink ? `ink-${s.ink}` : undefined}>
            <span className={styles.dot}>{i + 1}</span>
            <span><In text={s.text} icons={icons} />{s.note && <In as="span" className={styles.small} text={s.note} icons={icons} />}</span>
          </li>
        ))}
      </ol>
      {!reduce && !compact && steps.length > 1 && (
        <div className={styles.ctl}>
          <button type="button" onClick={() => setK((x) => Math.max(0, x - 1))}>‹ Back</button>
          <button type="button" onClick={() => setK((x) => Math.min(steps.length - 1, x + 1))}>Next step ›</button>
        </div>
      )}
    </div>
  )
}
